async def seed_levy_ledger():
    """Upsert all levy ledger entries. Safe to re-run."""
    client = AsyncMongoClient(os.environ['MONGO_URL'])
    db = client[os.environ['DB_NAME']]
    upserted = 0
    for entry in EAST_GATE_LEVY_LEDGER:
        result = await db.unit_levy_ledger.update_one(
            {'building_id': entry['building_id'], 'unit_number': entry['unit_number'], 'year': entry['year']},
            {'$set': entry, '$setOnInsert': {'created_at': entry.get('created_at', entry['updated_at'])}},
            upsert=True
        )
        if result.upserted_id or result.modified_count:
            upserted += 1
    print(f'Levy ledger: {upserted} entries upserted ({len(EAST_GATE_LEVY_LEDGER)} total)')
    client.close()


if __name__ == "__main__":
    asyncio.run(seed_levy_ledger())
